void commissSplitInsert()
{
    KCS_BOSCentrLocatCommissSplit locKCS_BOSCentrLocatCommissSplit;

    next commissSplitInsert();

    switch (sourceSplitTable.TableId)
    {
        case (tablenum(KCS_BOSCentrLocatCommissSplit)):
            locKCS_BOSCentrLocatCommissSplit = this.parmNewCommissSplit();
            if(locKCS_BOSCentrLocatCommissSplit.RecId)
            {
                ttsbegin;
                locKCS_BOSCentrLocatCommissSplit.selectForUpdate(true);
                locKCS_BOSCentrLocatCommissSplit.SalesGroup         = clsCommissSalesGroup;
                locKCS_BOSCentrLocatCommissSplit.ConditionModeID    = clsAVACBSConditionModeID;
                locKCS_BOSCentrLocatCommissSplit.CommissSplit       = clsAVACBSCommissSplit;
                locKCS_BOSCentrLocatCommissSplit.CommissionRate     = clsAVACBSCalcRate;
                locKCS_BOSCentrLocatCommissSplit.update();
                ttscommit;
            }
            break;
    }
}
